csApsConfigEntry = MibTableRow((1, 3, 6, 1, 4, 1, 9, 9, 126, 1, 2, 1, 1), ).setMaxAccess("notaccessible").setIndexNames((0, "CISCO-SONET-MIB", "csApsWorkingIndex"))
